package com.nagriksetu.application.controller;

import com.nagriksetu.application.dto.*;
import com.nagriksetu.application.service.IssueService;
import com.nagriksetu.application.service.AuthService;
import com.nagriksetu.application.entity.AppUser;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.util.List;

@RestController
@RequestMapping("/api/issues")
@CrossOrigin
public class IssueApiController {
    private final IssueService issueService; private final AuthService authService; private final com.nagriksetu.application.service.FileStorageService fileStorageService; private final com.nagriksetu.application.service.GroqPriorityService groqPriorityService;
    public IssueApiController(IssueService issueService, AuthService authService, com.nagriksetu.application.service.FileStorageService fileStorageService, com.nagriksetu.application.service.GroqPriorityService groqPriorityService) { this.issueService = issueService; this.authService = authService; this.fileStorageService = fileStorageService; this.groqPriorityService = groqPriorityService; }
    @GetMapping public ResponseEntity<?> findAll(HttpSession session) { AppUser user = authService.currentUser(session); if (user == null) return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build(); if (authService.isStaff(user)) return ResponseEntity.ok(issueService.findByDepartment(user.getDepartment()).stream().map(issue -> new IssueResponse(issue.getId(), issue.getTitle(), issue.getDescription(), issue.getCategory(), issue.getLocation(), issue.getLatitude(), issue.getLongitude(), issue.getImageUrl(), issue.getResolutionEvidenceUrl(), issue.getDepartment(), issue.getPriority(), issue.getStatus(), issue.getCreatedAt())).toList()); return ResponseEntity.ok(issueService.findByReporter(user.getId()).stream().map(issue -> new IssueResponse(issue.getId(), issue.getTitle(), issue.getDescription(), issue.getCategory(), issue.getLocation(), issue.getLatitude(), issue.getLongitude(), issue.getImageUrl(), issue.getResolutionEvidenceUrl(), issue.getDepartment(), issue.getPriority(), issue.getStatus(), issue.getCreatedAt())).toList()); }
    @PostMapping public ResponseEntity<?> create(@Valid @RequestBody IssueCreateRequest request, HttpSession session) { AppUser user = authService.currentUser(session); if (user == null || authService.isStaff(user)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); return ResponseEntity.status(HttpStatus.CREATED).body(issueService.create(request, user)); }
    @PostMapping(value = "/upload", consumes = MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> createWithImage(@RequestParam String title, @RequestParam String description, @RequestParam String category, @RequestParam String department, @RequestParam(required = false) String location, @RequestParam(required = false) Double latitude, @RequestParam(required = false) Double longitude, @RequestParam(required = false) MultipartFile image, HttpSession session) { AppUser user = authService.currentUser(session); if (user == null || authService.isStaff(user)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); try { if (image != null && !image.isEmpty() && !groqPriorityService.verifyReportImage(title, image).verified()) return ResponseEntity.badRequest().body(java.util.Map.of("message", "The uploaded image does not match the report title. Please choose a relevant photo.")); String imageUrl = fileStorageService.storeImage(image, "report"); return ResponseEntity.status(HttpStatus.CREATED).body(issueService.create(new IssueCreateRequest(title, description, category, department, location, latitude, longitude, imageUrl), user, image)); } catch (IllegalArgumentException exception) { return ResponseEntity.badRequest().body(java.util.Map.of("message", exception.getMessage())); } catch (IllegalStateException exception) { return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(java.util.Map.of("message", exception.getMessage())); } }
    @PatchMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id, @RequestBody IssueUpdateRequest request, HttpSession session) { AppUser user = authService.currentUser(session); if (user == null || !authService.isStaff(user)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); try { return ResponseEntity.ok(issueService.update(id, request, user.getDepartment())); } catch (SecurityException exception) { return ResponseEntity.status(HttpStatus.FORBIDDEN).body(java.util.Map.of("message", exception.getMessage())); } }
    @PostMapping(value = "/{id}/manage", consumes = MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> manage(@PathVariable Long id, @RequestParam(required = false) MultipartFile evidence, HttpSession session) { AppUser user = authService.currentUser(session); if (user == null || !authService.isStaff(user)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); try { return ResponseEntity.ok(issueService.updateWithEvidence(id, fileStorageService.storeImage(evidence, "resolution"), user.getDepartment())); } catch (SecurityException exception) { return ResponseEntity.status(HttpStatus.FORBIDDEN).body(java.util.Map.of("message", exception.getMessage())); } catch (IllegalArgumentException exception) { return ResponseEntity.badRequest().body(java.util.Map.of("message", exception.getMessage())); } }
    @DeleteMapping("/{id}/evidence") public ResponseEntity<?> clearEvidence(@PathVariable Long id, HttpSession session) { AppUser user = authService.currentUser(session); if (user == null || !authService.isStaff(user)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); try { return ResponseEntity.ok(issueService.clearResolutionEvidence(id, user.getDepartment())); } catch (SecurityException exception) { return ResponseEntity.status(HttpStatus.FORBIDDEN).body(java.util.Map.of("message", exception.getMessage())); } catch (IllegalArgumentException exception) { return ResponseEntity.badRequest().body(java.util.Map.of("message", exception.getMessage())); } }
}
